    private function profile(array $outcomes, array $control, array $decisions, array $capabilities): array
    {
        return ['outcomes' => $outcomes, 'control' => $control, 'decisions' => $decisions,
            'capabilities' => array_map(fn (array $item): array => ['en' => $item[0], 'fa' => $item[1], 'ps' => $item[2]], $capabilities)];
    }

